class AdManager{constructor(options={}){this.frequency=options.frequency || parseInt(window.AD_FREQUENCY || '12',10);this.adSenseClient=options.adSenseClient || window.GOOGLE_ADSENSE_CLIENT || null;this.adSlots={square:options.squareSlot || window.GOOGLE_AD_SLOT_SQUARE || null,banner:options.bannerSlot || window.GOOGLE_AD_SLOT_BANNER || null,native:options.nativeSlot || window.GOOGLE_AD_SLOT_NATIVE || null};this.userIsPremium=options.isPremium || false;this.adsDisabled=options.disabled || false;this.adCount=0;this.impressions=[];this.minItemsForAds=6;console.log('📢 [AD MANAGER] Initialized:',{frequency:this.frequency,enabled:this.shouldShowAds(),client:this.adSenseClient ? '✓':'✗',minItems:this.minItemsForAds});}shouldShowAds(){const currentPath=window.location.pathname;const excludedPaths=['/login','/signup','/auth/','/api/','/logout'];if(excludedPaths.some(path=> currentPath.includes(path))){console.log('📢 [AD MANAGER] Ads disabled for this page:',currentPath);return false;}return !this.userIsPremium && !this.adsDisabled;}shouldShowAdAtPosition(index){if(index===0)return false;if(!this.shouldShowAds())return false;return((index + 1)% this.frequency)===0;}createAdElement(adIndex,format='square'){const container=document.createElement('div');container.className='ad-container';container.setAttribute('data-ad-index',adIndex);container.setAttribute('data-ad-format',format);const label=document.createElement('div');label.className='ad-label';label.textContent='Advertisement';container.appendChild(label);if(this.adSenseClient && this.adSlots[format]){const adUnit=this.createAdSenseUnit(format);container.appendChild(adUnit);this.impressions.push({element:adUnit,index:adIndex,format:format,loaded:false});}else{const placeholder=this.createPlaceholder(format);container.appendChild(placeholder);}return container;}createAdSenseUnit(format){const ins=document.createElement('ins');ins.className='adsbygoogle';ins.setAttribute('data-ad-client',this.adSenseClient);ins.setAttribute('data-ad-slot',this.adSlots[format]);const dimensions=this.getAdDimensions(format);ins.style.display='inline-block';ins.style.width=dimensions.width;ins.style.height=dimensions.height;if(format==='native'){ins.setAttribute('data-ad-format','auto');ins.setAttribute('data-full-width-responsive','true');}else{ins.setAttribute('data-ad-format','rectangle');}return ins;}getAdDimensions(format){switch(format){case 'banner':return{width:'728px',height:'90px'};case 'native':return{width:'100%',height:'auto'};default:return{width:'300px',height:'250px'};}}createPlaceholder(format){const dimensions=this.getAdDimensions(format);const placeholder=document.createElement('div');placeholder.className='ad-demo-content ad-placeholder';placeholder.style.width=dimensions.width;placeholder.style.height=dimensions.height;placeholder.innerHTML=` <div class="ad-demo-text"> <strong>Ad Placeholder</strong><br> <small>Configure ads in .env</small><br> <span style="font-size:11px;opacity:0.7;">${dimensions.width}× ${dimensions.height}</span> </div> `;return placeholder;}insertAdsIntoContainer(container,itemSelector){if(!this.shouldShowAds())return;const items=Array.from(container.querySelectorAll(itemSelector));if(items.length < this.minItemsForAds){console.log(`📢 [AD MANAGER] Insufficient content(${items.length}< ${this.minItemsForAds}),no ads inserted`);return;}let insertedCount=0;items.forEach((item,index)=>{if(this.shouldShowAdAtPosition(index)){const ad=this.createAdElement(this.adCount,'square');item.parentNode.insertBefore(ad,item);insertedCount++;this.adCount++;}});console.log(`📢 [AD MANAGER] Inserted ${insertedCount}ads`);if(this.adSenseClient && insertedCount > 0){this.loadAdSenseAds();}}insertAdAtPosition(container,beforeElement,format='square'){if(!this.shouldShowAds())return null;const ad=this.createAdElement(this.adCount,format);container.insertBefore(ad,beforeElement);this.adCount++;if(this.adSenseClient){this.loadAdSenseAds();}return ad;}loadAdSenseAds(){if(!window.adsbygoogle){console.warn('⚠️ [AD MANAGER] AdSense script not loaded');return;}if(this.loadTimeout){clearTimeout(this.loadTimeout);}this.loadTimeout=setTimeout(()=>{const unloadedAds=this.impressions.filter(imp=> !imp.loaded);if(unloadedAds.length===0){return;}console.log(`📢 [AD MANAGER] Loading ${unloadedAds.length}new ad(s)...`);unloadedAds.forEach(impression=>{try{if(!impression.element.isConnected){console.warn(`⚠️ [AD MANAGER] Ad #${impression.index}element removed from DOM,skipping`);return;}(window.adsbygoogle=window.adsbygoogle || []).push({});impression.loaded=true;console.log(`✅ [AD MANAGER] Loaded ad #${impression.index}`);this.trackAdImpression(impression);}catch(e){console.error(`❌ [AD MANAGER] Error loading ad #${impression.index}:`,e.message);}});},100);}trackAdImpression(impression){if(window.activityTracker){window.activityTracker.track('ad_impression',{ad_index:impression.index,ad_format:impression.format,ad_frequency:this.frequency});}}setupLazyLoading(){if(!('IntersectionObserver' in window))return;const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const adContainer=entry.target;const adIndex=parseInt(adContainer.getAttribute('data-ad-index'),10);console.log(`👁️ [AD MANAGER] Ad #${adIndex}in viewport`);if(window.activityTracker){window.activityTracker.track('ad_viewable',{ad_index:adIndex});}observer.unobserve(adContainer);}});},{threshold:0.5,rootMargin:'50px'});document.querySelectorAll('.ad-container').forEach(ad=>{observer.observe(ad);});}}window.AdManager=AdManager;